def _placeholder(value, title, language):
    if not value or not str(value).strip() or str(value).strip() == str(title).strip():
        return True
    markers = ('Решение определяет будущий курс страны.', 'Последствия и условия показаны ниже.') if language == 'ru' else ('This decision determines the country’s future course.', 'Conditions and consequences are shown below.')
    return any(marker in str(value) for marker in markers)


def _fallback(tag, node):
    """Future-node fallback follows country context and actual effect type."""
    base = COUNTRY_CONTEXT.get(tag, ('Общая программа требует ясного мандата.', 'A common programme needs a clear mandate.'))
    effect = str(node.get('effect', ''))
    if 'aof_diplomacy.' in effect:
        tail = ('Направим предложение, оставив другой стороне право определить условия или отказаться. Подготовка ещё не означает заключения договора.', 'An offer leaves the other side free to set terms or refuse. Preparation does not itself conclude an agreement.')
    elif 'country_event' in effect:
        tail = ('Подготовим отдельное решение правительства: спор об условиях нельзя закрыть названием программы.', 'A separate government decision must address the terms; naming a programme cannot settle them.')
    elif 'set_politics' in effect:
        tail = ('Закрепим источник полномочий и правила участия; дальнейшую поддержку придётся оправдывать результатом.', 'We will establish authority and participation rules; continued support must be justified through results.')
    elif 'add_building_construction' in effect:
        tail = ('Создадим материальную опору задачи, вместо того чтобы требовать большего от учреждений без новых возможностей.', 'The task needs a material foundation rather than demands for more work without the capacity to deliver.')
    elif 'add_tech_bonus' in effect:
        tail = ('Сосредоточим прикладную работу на этом направлении: знание должно стать обслуживаемой практикой, а не обещанием мгновенного превосходства.', 'Applied work must turn knowledge into maintainable practice rather than promises of immediate superiority.')
    else:
        tail = ('Соберём политическую опору этого шага; конкурирующие приоритеты нужно согласовать перед следующим общим решением.', 'Political support for this step requires reconciling competing priorities before the next common decision.')
    return (base[0] + ' ' + tail[0], base[1] + ' ' + tail[1])


def national_descriptions(tag, nodes):
    """Return {id:(ru,en)} replacements only; preserve custom prose verbatim."""
    tag = str(tag).upper()
    prefix = 'aof_v03_' + tag.lower() + '_'
    result = {}
    for node in nodes:
        ident = str(node.get('id', ''))
        short = ident[len(prefix):] if ident.startswith(prefix) else ident
        old = (node.get('desc_ru', ''), node.get('desc_en', ''))
        generic = (_placeholder(old[0], node.get('ru', ''), 'ru'), _placeholder(old[1], node.get('en', ''), 'en'))
        if not any(generic):
            continue
        proposed = DESCRIPTIONS.get(tag, {}).get(short) or _fallback(tag, node)
        result[ident] = (proposed[0] if generic[0] else old[0], proposed[1] if generic[1] else old[1])
    return result
